import java.time.*;import java.time.temporal.ChronoUnit;abstract class Employee{String name;Employee(String n){name=n;}abstract boolean canTakeLeave(long days);}class FullTimeEmployee extends Employee{FullTimeEmployee(String n){super(n);}boolean canTakeLeave(long d){return d<=30;}}class PartTimeEmployee extends Employee{PartTimeEmployee(String n){super(n);}boolean canTakeLeave(long d){return d<=15;}}class Contractor extends Employee{Contractor(String n){super(n);}boolean canTakeLeave(long d){return d<=10;}}enum LeaveStatus{PENDING,APPROVED,REJECTED}class LeaveRequest{Employee employee;LocalDate start,end;LeaveStatus status=LeaveStatus.PENDING;LeaveRequest(Employee e,LocalDate s,LocalDate en){if(en.isBefore(s))throw new IllegalArgumentException();employee=e;start=s;end=en;}void review(boolean approve){if(status!=LeaveStatus.PENDING)throw new IllegalStateException();long d=ChronoUnit.DAYS.between(start,end)+1;status=approve&&employee.canTakeLeave(d)?LeaveStatus.APPROVED:LeaveStatus.REJECTED;}}public class Main{public static void main(String[]a){}}